import React, { useEffect, useState, useMemo } from "react";
import {
  Box,
  Typography,
  Grid,
  Card,
  Button,
  TextField,
  Badge,
  IconButton,
  Container,
} from "@mui/material";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
} from "@mui/material";

import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import { useDispatch, useSelector } from "react-redux";
import { useLocation, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { getProductsByConnection } from "../redux/slices/sellerProductSlice";
import { addToCart, getCart } from "../redux/slices/cartSlice";

export default function ViewProducts() {
  const dispatch = useDispatch();
  const location = useLocation();
  const navigate = useNavigate();
  const { connectionId, otherUserId } = location.state || {};
  const { allProducts } = useSelector((state) => state.products);
  const userId = useSelector((state) => state.user?.user?._id);
  const cart = useSelector((state) => state.cart?.cart);
  const [quantities, setQuantities] = useState({});
  const [localCartCount, setLocalCartCount] = useState(0);

  // Quantity Change Handler
  const handleQtyChange = (id, value) => {
    if (value < 0) return;
    setQuantities({ ...quantities, [id]: value });
  };

  // Add All to Cart
  const handleAddAll = async () => {
    const items = Object.entries(quantities)
      .filter(([id, qty]) => qty > 0)
      .map(([id, qty]) => ({
        productId: id,
        quantity: qty,
      }));

    if (items?.length === 0)
      return toast.info("Please enter quantity for at least one product.");

    try {
      await dispatch(addToCart({ userId, items })).unwrap();
      toast.success("Products added to cart!");
      // Update local cart count immediately
      const addedQty = items?.reduce((sum, item) => sum + item.quantity, 0);
      setLocalCartCount((prev) => prev + addedQty);
      const sellerIds = [
        ...new Set(allProducts.map((p) => p.user?._id).filter(Boolean)),
      ];
      await Promise?.all(
        sellerIds?.map((sellerId) =>
          dispatch(getCart({ userId, seller: sellerId })).unwrap()
        )
      );

      setQuantities({});
    } catch (error) {
      toast.error("Failed to add items to cart");
    }
  };

  // Fetch Products
  useEffect(() => {
    if (connectionId && otherUserId) {
      dispatch(getProductsByConnection({ connectionId, otherUserId }));
    }
  }, [dispatch, connectionId, otherUserId]);

  // Extract sellerIds and buyerCategories safely
  const sellerIds = useMemo(
    () => [...new Set(allProducts?.map((p) => p.user?._id).filter(Boolean))],
    [allProducts]
  );

  const buyerCategories = useMemo(
    () => [
      ...new Set(
        allProducts
          ?.flatMap((p) => p.productVisibility?.map((v) => v.buyerCategory))
          .filter(Boolean)
      ),
    ],
    [allProducts]
  );

  // Fetch cart whenever userId, sellerIds or buyerCategories change
  useEffect(() => {
    if (userId && sellerIds.length > 0) {
      dispatch(getCart({ userId, seller: sellerIds, buyerCategories }));
    }
  }, [dispatch, userId, sellerIds, buyerCategories]);

  // Compute total cart count
  const totalCartCount = useMemo(() => {
    const backendCount = Array.isArray(cart)
      ? cart.reduce((sum, item) => sum + (item.quantity || 0), 0)
      : 0;
    return backendCount + localCartCount;
  }, [cart, localCartCount]);

  return (
    <Box
      sx={{
        px: { xs: 2, md: 4 },
        py: 3,
        backgroundColor: "#f5f7fa",
        minHeight: "100vh",
      }}
    >
      <Typography
        fontWeight={700}
        fontSize={{ xs: 22, md: 28 }}
        mb={3}
        color="#22364a"
      >
        View Products
      </Typography>

      <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                #
              </TableCell>
              <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                Name
              </TableCell>
              <TableCell sx={{ fontWeight: 800, fontSize: "16px" }}>
                Price
              </TableCell>
              <TableCell
                sx={{ fontWeight: 800, fontSize: "16px", textAlign: "center" }}
              >
                Quantity
              </TableCell>
            </TableRow>
          </TableHead>

          <TableBody>
            {allProducts?.map((product, index) => (
              <TableRow key={product._id}>
                <TableCell sx={{ fontSize: "15px" }}>{index + 1}</TableCell>
                {/* Product Name */}
                <TableCell>
                  <Box
                    sx={{
                      color: "#22364a",
                      fontWeight: 600,
                      fontSize: "15px",
                      cursor: "pointer",
                      display: "inline-block",
                      "&:hover": {
                        textDecoration: "underline",
                        color: "#fb8900",
                      },
                    }}
                    onClick={() =>
                      navigate(
                        `/buyer-dashboard/product-details/${product._id}`,
                        {
                          state: { product },
                        }
                      )
                    }
                  >
                    {product.name}
                  </Box>
                </TableCell>

                {/* Price */}
                <TableCell
                  sx={{ fontSize: "15px", color: "#fb8900", fontWeight: 700 }}
                >
                  ₹{product.price}
                </TableCell>

                {/* Qty Input */}
                <TableCell sx={{ textAlign: "center" }}>
                  <TextField
                    type="number"
                    size="small"
                    value={quantities[product._id] || 0}
                    onChange={(e) =>
                      handleQtyChange(
                        product._id,
                        parseInt(e.target.value) || 0
                      )
                    }
                    sx={{
                      width: "70px",
                      fontSize: "15px",
                      "& .MuiInputBase-root": {
                        borderRadius: "8px",
                        backgroundColor: "#f0f0f0",
                      },
                    }}
                  />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      <Box
        sx={{
          right: 0,
          display: "flex",
          gap: 2,
          mt: 3, 
          px: { xs: 0, md: 0 },
          py: 1.5,
          borderRadius: 3,
          alignItems: "center",
        }}
      >
        {/* Add to Cart Button */}
        <Button
          variant="contained"
          onClick={handleAddAll}
          sx={{
            px: 4,
            py: 1.5,
            borderRadius: 3,
            fontWeight: 600,
            color: "#fff",
            backgroundColor: "#fb8900",
            "&:hover": {
              backgroundColor: "#fb8a00e2",
            },
          }}
        >
          Add to Cart
        </Button>

        {/* Cart Icon with Badge */}
        <Badge
          badgeContent={totalCartCount}
          color="primary"
          overlap="circular"
          anchorOrigin={{ vertical: "top", horizontal: "right" }}
        >
          <IconButton
            onClick={() => {
              const sellerIds = [
                ...new Set(
                  allProducts?.map((p) => p.user?._id).filter(Boolean)
                ),
              ];
              const buyerCategories = [
                ...new Set(
                  allProducts
                    ?.flatMap((p) =>
                      p.productVisibility?.map((v) => v.buyerCategory)
                    )
                    .filter(Boolean)
                ),
              ];
              navigate("/buyer-dashboard/cart", {
                state: { buyerCategories, sellerIds, userId },
              });
            }}
            sx={{
              backgroundColor: "#e0f2f1",
              color: "#22364a",
              borderRadius: "50%",
              width: 50,
              height: 50,
              "&:hover": {
                backgroundColor: "#b2dfdb",
              },
            }}
          >
            <ShoppingCartIcon fontSize="medium" />
          </IconButton>
        </Badge>
      </Box>
    </Box>
  );
}

