import React, { useEffect, useState } from "react";
import {
  Box,
  Grid,
  Typography,
  Avatar,
  Card,
  CardContent,
  CardMedia,
  Button,
  Container,
  CircularProgress,
} from "@mui/material";
import { motion } from "framer-motion";
import { Link as RouterLink } from "react-router-dom";

// --- MOCK BLOG POSTS (SAMPLE DATA) ---
export const mockBlogs = Array.from({ length: 10 }, (_, i) => ({
  id: i + 1,
  title: `The Future of AI in Business Operations #${i + 1}`,
  excerpt:
    "Discover how AI is reshaping industries, from automating tasks to providing deep insights...",
  authorName:
    i % 3 === 0 ? "Jane Doe" : i % 3 === 1 ? "John Smith" : "Alex Ray",
  authorAvatar: `https://i.pravatar.cc/150?img=${i + 30}`,
  publishDate: `September ${Math.floor(Math.random() * 30) + 1}, 2025`,
  imageUrl: `https://picsum.photos/seed/blog${i + 1}/800/600`,
}));

// --- Animation variants for Framer Motion ---
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.5,
    },
  },
};

const HomeBlogSection = () => {
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    const timer = setTimeout(() => {
      setBlogs(mockBlogs);
      setLoading(false);
    }, 1200);

    return () => clearTimeout(timer);
  }, []);

  // show only 3 blogs on home
  const visibleBlogs = blogs.slice(0, 3);

  return (
    <Box
      sx={{
        width: "100%",
        bgcolor: "#ffffff",
        py: { xs: 6, md: 10 },
        px: { xs: 2, sm: 4 },
      }}
    >
      <Container maxWidth="lg">
        {/* Section Title */}
        <Box textAlign="center" mb={{ xs: 5, md: 8 }}>
          <Typography
            variant="h3"
            component="h2"
            sx={{
              fontWeight: 800,
              color: "#101828",
              fontSize: { xs: "2rem", sm: "2.5rem", md: "3rem" },
            }}
          >
            Latest <Box component="span" sx={{ color: "#28a745" }}>Insights</Box>
          </Typography>
          <Typography
            variant="body1"
            sx={{
              color: "text.secondary",
              mt: 2,
              maxWidth: "700px",
              mx: "auto",
              fontSize: { xs: "1rem", md: "1.125rem" },
            }}
          >
            Explore our latest articles on technology, business, and innovation. Fresh perspectives and practical guides for your growth.
          </Typography>
        </Box>

        {loading && (
          <Box textAlign="center" sx={{ py: 6 }}>
            <CircularProgress />
            <Typography sx={{ mt: 2 }}>Loading Blogs...</Typography>
          </Box>
        )}

        {!loading && (
          <>
            <motion.div
              variants={containerVariants}
              initial="hidden"
              animate="visible"
            >
              <Grid container spacing={4} justifyContent="center" alignItems="stretch">
                {visibleBlogs.map((blog) => (
                  <Grid item xs={12} sm={6} md={4} key={blog.id}>
                    <motion.div variants={itemVariants} style={{ height: "100%" }}>
                      <Card
                        sx={{
                          height: "100%",
                          borderRadius: "16px",
                          boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
                          display: "flex",
                          flexDirection: "column",
                          transition: "transform 0.3s ease, box-shadow 0.3s ease",
                          "&:hover": {
                            transform: "translateY(-8px)",
                            boxShadow: "0 10px 25px -5px rgba(0, 0, 0, 0.1)",
                          },
                        }}
                      >
                        <CardMedia
                          component="img"
                          height="200"
                          image={blog.imageUrl}
                          alt={blog.title}
                        />
                        <CardContent
                          sx={{
                            p: 3,
                            flexGrow: 1,
                            display: "flex",
                            flexDirection: "column",
                          }}
                        >
                          <Typography
                            variant="h6"
                            component="h3"
                            fontWeight={700}
                            gutterBottom
                            sx={{
                              color: "#111827",
                              display: "-webkit-box",
                              WebkitBoxOrient: "vertical",
                              WebkitLineClamp: 2,
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                            }}
                          >
                            {blog.title}
                          </Typography>
                          <Typography
                            variant="body2"
                            color="text.secondary"
                            sx={{
                              my: 2,
                              flexGrow: 1,
                              display: "-webkit-box",
                              WebkitBoxOrient: "vertical",
                              WebkitLineClamp: 3,
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                            }}
                          >
                            {blog.excerpt}
                          </Typography>

                          {/* Read More Button */}
                          <Button
                            component={RouterLink}
                            to={`/blogs/${blog.id}`}
                            variant="outlined"
                            sx={{
                              mt: 2,
                              alignSelf: "flex-start",
                              borderRadius: "30px",
                              px: 3,
                              fontWeight: 600,
                              textTransform: "none",
                              fontSize: "0.9rem",
                              color: "#28a745",
                              borderColor: "#28a745",
                              "&:hover": {
                                bgcolor: "#28a745",
                                color: "#fff",
                              },
                            }}
                          >
                            Read More
                          </Button>

                          <Box
                            sx={{
                              mt: "auto",
                              display: "flex",
                              alignItems: "center",
                              gap: 2,
                              pt: 2,
                              borderTop: "1px solid #f3f4f6",
                            }}
                          >
                            <Avatar
                              src={blog.authorAvatar}
                              alt={blog.authorName}
                              sx={{ width: 40, height: 40 }}
                            />
                            <Box>
                              <Typography variant="subtitle2" fontWeight={600}>
                                {blog.authorName}
                              </Typography>
                              <Typography
                                variant="caption"
                                color="text.secondary"
                              >
                                {blog.publishDate}
                              </Typography>
                            </Box>
                          </Box>
                        </CardContent>
                      </Card>
                    </motion.div>
                  </Grid>
                ))}
              </Grid>
            </motion.div>

            {/* View All Blogs Button */}
            <Box textAlign="center" sx={{ mt: 6 }}>
              <Button
                component={RouterLink}
                to="/blogs"
                variant="contained"
                sx={{
                  borderRadius: "50px",
                  px: 5,
                  py: 1.5,
                  fontWeight: 600,
                  bgcolor: "#28a745",
                  color: "#fff",
                  textTransform: "none",
                  fontSize: "1rem",
                  boxShadow: "0 4px 12px rgba(40, 167, 69, 0.3)",
                  "&:hover": {
                    bgcolor: "#218838",
                    boxShadow: "0 6px 16px rgba(40, 167, 69, 0.4)",
                    transform: "translateY(-2px)",
                  },
                }}
              >
                Explore All Blogs
              </Button>
            </Box>
          </>
        )}
      </Container>
    </Box>
  );
};

export default HomeBlogSection;
